function validateRows(input){const seen=new Set();const accepted=[],rejected=[];for(const row of input){const reasons=[];if(seen.has(row.id))reasons.push('Duplicate ID');seen.add(row.id);if(!row.customer.trim())reasons.push('Missing customer');if(typeof row.amount!=='number'||!Number.isFinite(row.amount)||row.amount<=0)reasons.push('Amount must be a positive number');if(reasons.length)rejected.push({...row,reasons});else accepted.push(row)}return{accepted,rejected,total:accepted.reduce((s,r)=>s+r.amount,0)}}
