const stopWords=new Set('a an the is are was were be to for of and or in on at it its my your what how why when who which will can do does about with this that me tell please'.split(' '));
function tokens(s){return [...new Set((s.toLowerCase().match(/[a-z0-9]+/g)||[]).filter(w=>!stopWords.has(w)&&w.length>2).map(w=>w.replace(/(ing|ed|s)$/,'')))];}
function retrieve(text,question){const paragraphs=text.split(/\n\s*\n/).map(s=>s.trim()).filter(Boolean);let keys=tokens(question);if(/price|cost|budget/.test(question.toLowerCase()))keys.push('pric');if(/deliver/.test(question.toLowerCase()))keys.push('deliverable');if(/private|privacy|sensitive/.test(question.toLowerCase()))keys.push('privacy','sensitive');return paragraphs.map((text,index)=>({text,index:index+1,score:tokens(text).filter(w=>keys.includes(w)).length})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.index-b.index).slice(0,2)}
function runRetrieval(){const text=$('#document').value.trim(),question=$('#question').value.trim(),out=$('#retrieval-result');out.replaceChildren();if(!text||!question){out.textContent='Add document text and a question to find relevant passages.';return}if(new TextEncoder().encode(text).length>20000){out.textContent='Document is too large. Use text up to 20 KB.';return}const matches=retrieve(text,question);const heading=document.createElement('strong');heading.textContent=matches.length?'RETRIEVED PASSAGES / EXACT SOURCE TEXT':'NO MATCHING PASSAGE';out.append(heading);if(!matches.length){const p=document.createElement('p');p.textContent='No shared terms were found. Rephrase your question using words from the source. This demo does not invent an answer.';out.append(p);return}matches.forEach(m=>{const quote=document.createElement('blockquote');quote.textContent=m.text;const citation=document.createElement('button');citation.className='text-button';citation.textContent=`Source paragraph ${m.index} · inspect text ↗`;citation.addEventListener('click',()=>{const textarea=$('#document');const start=textarea.value.indexOf(m.text);textarea.focus();textarea.setSelectionRange(Math.max(0,start),Math.max(0,start)+m.text.length)});out.append(quote,citation)});const note=document.createElement('p');note.className='fine';note.textContent='Matching passages can contain the answer or related context. No answer is generated or inferred.';out.append(note)}
const sample=$('#document').value;
$('#question-form').addEventListener('submit',e=>{e.preventDefault();runRetrieval()});
$$('[data-question]').forEach(b=>b.addEventListener('click',()=>{$('#question').value=b.dataset.question;runRetrieval()}));
$('#reset-demo').addEventListener('click',()=>{$('#document').value=sample;$('#upload').value='';$('#upload-status').textContent='Sample restored.';$('#question').value='What will the assistant deliver?';runRetrieval()});
$('#upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const status=$('#upload-status');if(!/\.txt$/i.test(file.name)||file.size>20000){status.textContent='Choose a .txt file no larger than 20 KB.';e.target.value='';return}try{const text=await file.text();if(!text.trim()||text.includes('\u0000'))throw new Error('Invalid text');$('#document').value=text;status.textContent=`Loaded ${file.name} locally. Nothing was uploaded.`;runRetrieval()}catch{status.textContent='Could not read that file. Try a plain UTF-8 .txt file.'}});
