$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{buildMode=b.dataset.mode;buildStep=0;$$('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paintBuild()}));$('#run-build').addEventListener('click',()=>{buildStep=buildStep===3?0:buildStep+1;paintBuild()});paintBuild();
function conceptUI(id){if(id==='invoice')return `<div class="demo-caption">PLAY WITH THE PROTOTYPE / SAMPLE DATA ONLY</div><label for="invoice-text">Edit the sample invoice</label><textarea id="invoice-text" rows="5">Invoice: INV-2048\nClient: Sample Studio\nAmount: 600\nDue: 2026-11-15</textarea><button class="button primary" id="parse-invoice">Extract the fields ↗</button><pre id="invoice-output" aria-live="polite"></pre>`;
if(id==='leads')return `<div class="demo-caption">TRY THE RULES / FICTIONAL SALES MODEL</div><label for="lead-budget">Budget fit: <output id="budget-value">70</output>/100</label><input id="lead-budget" type="range" min="0" max="100" value="70"><label for="lead-fit">Service fit: <output id="fit-value">90</output>/100</label><input id="lead-fit" type="range" min="0" max="100" value="90"><label for="lead-urgency">Urgency: <output id="urgency-value">80</output>/100</label><input id="lead-urgency" type="range" min="0" max="100" value="80"><div id="lead-output" class="big-output" aria-live="polite"></div><p>Score = 30% budget + 50% service fit + 20% urgency. An illustrative prioritization rule.</p>`;
if(id==='travel')return `<div class="demo-caption">LOCAL ITINERARY GENERATOR / ILLUSTRATIVE PLANS</div><label for="travel-city">Pick a city</label><select id="travel-city"><option>Kyoto</option><option>Lisbon</option><option>Jaipur</option></select><label for="travel-style">Choose your pace</label><select id="travel-style"><option>Slow & curious</option><option>Art & architecture</option><option>Food & wandering</option></select><button id="plan-trip" class="button primary">Make a little plan ↗</button><div id="trip-output" aria-live="polite"></div><p>Sample inspiration, not live travel advice. Opening times, prices and bookings are not checked.</p>`;
return `<div class="demo-caption">YOUR BROWSER-LOCAL FOCUS SPACE</div><label for="focus-task">One thing to work on</label><input id="focus-task" maxlength="100" placeholder="What deserves your attention?"><label for="focus-duration">Session length</label><select id="focus-duration"><option value="1500">25 minutes</option><option value="300">5 minutes</option><option value="10">10-second test</option></select><div class="big-output" id="timer-display" role="timer">25:00</div><div class="timer-buttons"><button id="timer-start" class="button primary">Start focusing ▶</button><button id="timer-reset" class="button">Reset ↻</button></div><p id="timer-status" role="status">Ready when you are. Closing this dialog ends the session.</p>`;}
let focusInterval=null;
$('#case-dialog').addEventListener('close',()=>{clearInterval(focusInterval);focusInterval=null});
function bindConcept(id){if(id==='invoice'){$('#parse-invoice').addEventListener('click',()=>{const text=$('#invoice-text').value;const get=k=>(text.match(new RegExp('^'+k+':\\s*(.+)$','mi'))||[])[1]?.trim()||'';const data={invoice:get('Invoice'),client:get('Client'),amount:get('Amount'),due:get('Due')};const errors=[];for(const [k,v]of Object.entries(data))if(!v)errors.push('Missing '+k);if(data.amount&&(!Number.isFinite(Number(data.amount))||Number(data.amount)<=0))errors.push('Amount must be positive');if(data.due&&!/^\d{4}-\d{2}-\d{2}$/.test(data.due))errors.push('Due date must use YYYY-MM-DD');$('#invoice-output').textContent=errors.length?errors.join('\n'):JSON.stringify({...data,amount:Number(data.amount),status:'Validated sample'},null,2)});return}
if(id==='leads'){const update=()=>{const b=Number($('#lead-budget').value),f=Number($('#lead-fit').value),u=Number($('#lead-urgency').value);$('#budget-value').textContent=b;$('#fit-value').textContent=f;$('#urgency-value').textContent=u;const score=Math.round(b*.3+f*.5+u*.2);$('#lead-output').textContent=`${score}/100 · ${score>=75?'High priority':score>=45?'Worth exploring':'Lower priority'}`};['budget','fit','urgency'].forEach(k=>$('#lead-'+k).addEventListener('input',update));update();return}
if(id==='travel'){$('#plan-trip').addEventListener('click',()=>{const city=$('#travel-city').value,style=$('#travel-style').value;const activities={'Kyoto':['A quiet garden walk','An architecture sketch stop','A neighborhood café'],'Lisbon':['A riverside stroll','A tiled-facade photo walk','A small neighborhood bakery'],'Jaipur':['A morning courtyard walk','An old-city architecture trail','A local market food stop']};const start=style==='Art & architecture'?1:style==='Food & wandering'?2:0;$('#trip-output').innerHTML=`<h3>A little day in ${city}</h3><ol>${[0,1,2].map((_,i)=>`<li><strong>${['Morning','Afternoon','Evening'][i]}</strong> · ${activities[city][(i+start)%3]}</li>`).join('')}</ol>`});return}
let remaining=1500,running=false,endTime=0;const render=()=>{$('#timer-display').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`};const pause=()=>{clearInterval(focusInterval);running=false;$('#timer-start').textContent='Resume ▶'};$('#focus-duration').addEventListener('change',()=>{pause();remaining=Number($('#focus-duration').value);render();$('#timer-start').textContent='Start focusing ▶';$('#timer-status').textContent='Ready when you are.'});$('#timer-start').addEventListener('click',()=>{if(running){remaining=Math.max(0,Math.ceil((endTime-Date.now())/1000));pause();render();$('#timer-status').textContent='Paused. Take a breath.';return}if(remaining===0)remaining=Number($('#focus-duration').value);running=true;endTime=Date.now()+remaining*1000;$('#timer-start').textContent='Pause Ⅱ';$('#timer-status').textContent=$('#focus-task').value?'Working on: '+$('#focus-task').value:'One thing at a time.';focusInterval=setInterval(()=>{remaining=Math.max(0,Math.ceil((endTime-Date.now())/1000));render();if(!remaining){pause();$('#timer-start').textContent='Start again ↻';$('#timer-status').textContent='Session complete. A little progress counts.'}},250)});$('#timer-reset').addEventListener('click',()=>{pause();remaining=Number($('#focus-duration').value);render();$('#timer-start').textContent='Start focusing ▶';$('#timer-status').textContent='Reset. Ready when you are.'});}
